type typedRuntimeFixtureSnapshot struct {
	ProjectID string `json:"project_id"`
	SessionID string `json:"session_id"`
	WorkspaceRef string `json:"workspace_ref"`
	ModelConfigRef string `json:"model_config_ref"`
	NativeSessionRef string `json:"native_session_ref"`
	CoreBuildID string `json:"core_build_id"`
	ProtocolVersion string `json:"protocol_version"`
	Revision int64 `json:"revision"`
	EventSequence int64 `json:"event_sequence"`
	RunID *string `json:"active_run_id"`
	Writer *typedRuntimeFixtureWriter `json:"writer"`
	Preserved string `json:"-"`
}

type typedRuntimeFixtureBinding struct {
	ProjectID, SessionID, OwnerClientID, LeaseExpiresAt string
	WorkspaceRef, ModelConfigRef, NativeSessionRef string
	Revision, WriterEpoch int64
}

// The production schema validates the complete snapshot before this typed
// projection. JSON -> int64 preserves integer values without a float64 cast.
func typedRuntimeFixtureSnapshotBinding(doc *SchemaDoc, raw map[string]any) (typedRuntimeFixtureSnapshot, error) {
	var snapshot typedRuntimeFixtureSnapshot
	if doc == nil {
		return snapshot, fmt.Errorf("typed snapshot schema required")
	}
	if err := doc.ValidateDef("SessionSnapshot", normalizeNumbers(raw)); err != nil {
		return snapshot, err
	}
	encoded, err := json.Marshal(raw)
	if err != nil {
		return snapshot, err
	}
	if err = json.Unmarshal(encoded, &snapshot); err != nil {
		return snapshot, err
	}
	if snapshot.ProjectID == "" || snapshot.SessionID == "" || snapshot.WorkspaceRef == "" ||
		snapshot.ModelConfigRef == "" || snapshot.NativeSessionRef == "" || snapshot.CoreBuildID == "" ||
		snapshot.ProtocolVersion != ProtocolV2 || snapshot.Revision < 1 || snapshot.EventSequence < 0 ||
		(snapshot.Writer != nil && (snapshot.Writer.ClientID == "" || snapshot.Writer.Epoch < 1)) {
		return snapshot, fmt.Errorf("typed snapshot binding incomplete")
	}
	var preserved map[string]json.RawMessage
	if err = json.Unmarshal(encoded, &preserved); err != nil {
		return snapshot, err
	}
	// These are the only snapshot fields that a synchronous ownership change
	// may alter. Goal/run/queue/resume flags and all identity bindings remain.
	for _, name := range []string{"revision", "writer", "event_sequence", "updated_at"} {
		delete(preserved, name)
	}
	snapshot.Preserved = Digest(Bytes(preserved))
	return snapshot, nil
}

func typedRuntimeFixtureAttachSnapshot(doc *SchemaDoc, env *Envelope, reply *Response) (typedRuntimeFixtureSnapshot, error) {
	var empty typedRuntimeFixtureSnapshot
	if env == nil || reply == nil || deref(env.CommandID) == "" ||
		deref(env.Method) != "session.attach" || deref(reply.Status) != "COMPLETED" ||
		deref(reply.Method) != "session.attach" || deref(reply.ProtocolVersion) != ProtocolV2 ||
		deref(reply.CommandID) != deref(env.CommandID) || deref(reply.SessionID) != deref(env.SessionID) ||
		reply.ErrorCode != nil || reply.Error != nil || reply.Revision == nil || *reply.Revision < 1 {
		return empty, fmt.Errorf("attach original terminal identity mismatch")
	}
	if doc == nil {
		return empty, fmt.Errorf("attach result schema required")
	}
	if err := ValidateResultAgainstMethod("session.attach", reply, doc); err != nil {
		return empty, err
	}
	acquired, ok := reply.Result["write_owner_acquired"].(bool)
	if !ok || !acquired {
		return empty, fmt.Errorf("attach has no completed write ownership")
	}
	raw, ok := reply.Result["snapshot"].(map[string]any)
	if !ok {
		return empty, fmt.Errorf("attach snapshot missing")
	}
	snapshot, err := typedRuntimeFixtureSnapshotBinding(doc, raw)
	if err != nil {
		return empty, err
	}
	if snapshot.ProjectID != deref(env.ProjectID) || snapshot.SessionID != deref(env.SessionID) ||
		snapshot.Revision != *reply.Revision || snapshot.Writer == nil ||
		snapshot.Writer.ClientID != deref(env.ClientID) {
		return empty, fmt.Errorf("attach snapshot differs from original command")
	}
	return snapshot, nil
}

// This fixture is for ordinary (not restored) synchronous attach. It neither
// manufactures settlement nor converts an ACK/read-only response to completion.
func typedRuntimeFixtureAttachTransition(before, after typedRuntimeFixtureSnapshot, client string, started, finished time.Time) (bool, error) {
	if before.Writer == nil || after.Writer == nil || client == "" || finished.Before(started) ||
		before.ProjectID != after.ProjectID || before.SessionID != after.SessionID ||
		before.WorkspaceRef != after.WorkspaceRef || before.ModelConfigRef != after.ModelConfigRef ||
		before.NativeSessionRef != after.NativeSessionRef || before.CoreBuildID != after.CoreBuildID ||
		before.ProtocolVersion != ProtocolV2 || after.ProtocolVersion != ProtocolV2 ||
		before.Revision < 1 || after.Revision < 1 || before.Writer.Epoch < 1 || after.Writer.Epoch < 1 ||
		before.EventSequence < 0 || after.EventSequence < 0 || before.Preserved == "" || before.Preserved != after.Preserved ||
		after.Writer.ClientID != client {
		return false, fmt.Errorf("attach changed fixture identity or protected snapshot state")
	}
	oldExpiry, oldErr := time.Parse(time.RFC3339Nano, before.Writer.ExpiresAt)
	newExpiry, newErr := time.Parse(time.RFC3339Nano, after.Writer.ExpiresAt)
	if oldErr != nil || newErr != nil || !newExpiry.After(finished) {
		return false, fmt.Errorf("attach writer lease is not valid")
	}
	if after.Writer.Epoch == before.Writer.Epoch {
		if before.Writer.ClientID != client || !started.Before(oldExpiry) ||
			after.Revision != before.Revision || after.EventSequence != before.EventSequence {
			return false, fmt.Errorf("lease renewal changed generation or used an expired owner")
		}
		return false, nil
	}
	if after.Writer.Epoch-before.Writer.Epoch != 1 || after.Revision-before.Revision != 2 ||
		after.EventSequence-before.EventSequence != 1 ||
		(before.Writer.ClientID == client && finished.Before(oldExpiry)) {
		return false, fmt.Errorf("attach did not perform one permitted synchronous transfer")
	}
	return true, nil
}

func typedRuntimeFixtureReadSnapshot(t *testing.T, f *fixture, service *ClientService, session, client string) (*Response, typedRuntimeFixtureSnapshot) {
	t.Helper()
	reply := muClientCall(t, f, service, &Envelope{ProtocolVersion: strptr(ProtocolV2), CommandID: strptr(ID()),
		ClientID: &client, ProjectID: &f.project, SessionID: &session, Method: strptr("session.get"), Payload: Bytes(Object{})})
	snapshot, err := typedRuntimeFixtureSnapshotBinding(service.Doc, reply.Result)
	if err != nil || snapshot.ProjectID != f.project || snapshot.SessionID != session ||
		reply.Revision == nil || *reply.Revision != snapshot.Revision {
		t.Fatalf("typed fixture public snapshot mismatch: %v", err)
	}
	return reply, snapshot
}

func typedRuntimeFixtureReadAttachEvents(t *testing.T, f *fixture, service *ClientService, session, client string, after int64) (*Response, ClientEventPage) {
	t.Helper()
	reply := muClientCall(t, f, service, &Envelope{ProtocolVersion: strptr(ProtocolV2), CommandID: strptr(ID()),
		ClientID: &client, ProjectID: &f.project, SessionID: &session, Method: strptr("session.events"),
		Payload: Bytes(Object{"after_sequence": after, "limit": 2})})
	var page ClientEventPage
	if err := json.Unmarshal(Bytes(reply.Result), &page); err != nil {
		t.Fatal(err)
	}
	return reply, page
}

func attachTypedRuntimeFixture(t *testing.T, f *fixture, service *ClientService, created *Response, client string) typedRuntimeFixtureBinding {
	t.Helper()
	if created == nil || created.SessionID == nil || created.Revision == nil ||
		deref(created.Status) != "COMPLETED" || deref(created.Method) != "session.create" {
		t.Fatal("typed fixture creation lacks Session identity")
	}
	creation, err := typedRuntimeFixtureSnapshotBinding(service.Doc, created.Result)
	if err != nil || creation.ProjectID != f.project || creation.SessionID != deref(created.SessionID) || creation.Revision != *created.Revision {
		t.Fatalf("typed fixture creation binding invalid: %v", err)
	}
	_, before := typedRuntimeFixtureReadSnapshot(t, f, service, creation.SessionID, client)
	if before.WorkspaceRef != creation.WorkspaceRef || before.ModelConfigRef != creation.ModelConfigRef ||
		before.NativeSessionRef != creation.NativeSessionRef || before.CoreBuildID != creation.CoreBuildID {
		t.Fatal("typed fixture creation bindings changed before attach")
	}
	env := &Envelope{ProtocolVersion: strptr(ProtocolV2), CommandID: strptr(ID()), ClientID: &client,
		ProjectID: &f.project, SessionID: created.SessionID, ExpectedRevision: revPtr(before.Revision),
		Method: strptr("session.attach"), Payload: Bytes(Object{"after_sequence": before.EventSequence, "request_write_owner": true})}
	started := time.Now().UTC()
	reply := muClientCall(t, f, service, env)
	finished := time.Now().UTC()
	after, err := typedRuntimeFixtureAttachSnapshot(service.Doc, env, reply)
	if err != nil {
