721:func attachTypedRuntimeFixture(t *testing.T, f *fixture, service *ClientService, created *Response, client string) typedRuntimeFixtureBinding {
722:	t.Helper()
723:	if created == nil || created.SessionID == nil || created.Revision == nil ||
724:		deref(created.Status) != "COMPLETED" || deref(created.Method) != "session.create" {
725:		t.Fatal("typed fixture creation lacks Session identity")
726:	}
727:	creation, err := typedRuntimeFixtureSnapshotBinding(service.Doc, created.Result)
728:	if err != nil || creation.ProjectID != f.project || creation.SessionID != deref(created.SessionID) || creation.Revision != *created.Revision {
729:		t.Fatalf("typed fixture creation binding invalid: %v", err)
