731:	_, before := typedRuntimeFixtureReadSnapshot(t, f, service, creation.SessionID, client)
732:	if before.WorkspaceRef != creation.WorkspaceRef || before.ModelConfigRef != creation.ModelConfigRef ||
733:		before.NativeSessionRef != creation.NativeSessionRef || before.CoreBuildID != creation.CoreBuildID {
734:		t.Fatal("typed fixture creation bindings changed before attach")
735:	}
736:	env := &Envelope{ProtocolVersion: strptr(ProtocolV2), CommandID: strptr(ID()), ClientID: &client,
737:		ProjectID: &f.project, SessionID: created.SessionID, ExpectedRevision: revPtr(before.Revision),
738:		Method: strptr("session.attach"), Payload: Bytes(Object{"after_sequence": before.EventSequence, "request_write_owner": true})}
739:	started := time.Now().UTC()
740:	reply := muClientCall(t, f, service, env)
741:	finished := time.Now().UTC()
742:	after, err := typedRuntimeFixtureAttachSnapshot(service.Doc, env, reply)
743:	if err != nil {
744:		t.Fatal(err)
745:	}
746:	transferred, err := typedRuntimeFixtureAttachTransition(before, after, client, started, finished)
747:	if err != nil {
748:		t.Fatal(err)
749:	}
750:	current, currentBinding := typedRuntimeFixtureReadSnapshot(t, f, service, after.SessionID, client)
751:	if !bytes.Equal(Bytes(reply.Result["snapshot"]), Bytes(current.Result)) ||
752:		currentBinding.Revision != after.Revision || currentBinding.Writer == nil || *currentBinding.Writer != *after.Writer {
753:		t.Fatal("attach terminal differs from actual public Session state")
754:	}
755:	eventsReply, page := typedRuntimeFixtureReadAttachEvents(t, f, service, after.SessionID, client, before.EventSequence)
756:	if page.HasMore || page.HighWatermark != after.EventSequence || page.NextSequence != after.EventSequence {
757:		t.Fatal("attach public journal cursor differs from terminal")
758:	}
759:	if !transferred {
