761:			t.Fatal("lease-only renewal emitted a handoff")
762:		}
763:	} else {
764:		if len(page.Events) != 1 {
765:			t.Fatal("writer transfer lacks its unique committed CLIENT_HANDOFF")
766:		}
767:		event := page.Events[0]
768:		if deref(event.Kind) != "CLIENT_HANDOFF" || deref(event.CommandID) != deref(env.CommandID) ||
769:			deref(event.SessionID) != after.SessionID || deref(event.RunID) != deref(after.RunID) ||
770:			deref(event.ProtocolVersion) != ProtocolV2 || event.Sequence == nil || *event.Sequence != after.EventSequence {
771:			t.Fatal("handoff event differs from the exact attach command")
772:		}
773:		var payload struct {
774:			PreviousClientID string `json:"previous_client_id"`
775:			TargetClientID string `json:"target_client_id"`
776:			PreviousEpoch int64 `json:"previous_epoch"`
777:			Writer *typedRuntimeFixtureWriter `json:"writer"`
778:			EffectiveAt string `json:"effective_at"`
779:		}
780:		decoder := json.NewDecoder(bytes.NewReader(event.Payload))
781:		decoder.DisallowUnknownFields()
782:		if err := decoder.Decode(&payload); err != nil {
783:			t.Fatal(err)
784:		}
785:		var trailing any
786:		if err := decoder.Decode(&trailing); err != io.EOF {
787:			t.Fatal("handoff payload contains trailing data")
