797:	if !replay || !bytes.Equal(Bytes(reply), Bytes(again)) {
798:		t.Fatal("attach original command did not replay its exact terminal")
799:	}
800:	postReplay, _ := typedRuntimeFixtureReadSnapshot(t, f, service, after.SessionID, client)
801:	replayedEvents, _ := typedRuntimeFixtureReadAttachEvents(t, f, service, after.SessionID, client, before.EventSequence)
802:	if !bytes.Equal(Bytes(current.Result), Bytes(postReplay.Result)) || !bytes.Equal(Bytes(eventsReply.Result), Bytes(replayedEvents.Result)) {
803:		t.Fatal("attach replay repeated a lease write or journal transfer")
804:	}
805:	return typedRuntimeFixtureBinding{ProjectID: after.ProjectID, SessionID: after.SessionID,
806:		OwnerClientID: after.Writer.ClientID, LeaseExpiresAt: after.Writer.ExpiresAt,
807:		WorkspaceRef: after.WorkspaceRef, ModelConfigRef: after.ModelConfigRef, NativeSessionRef: after.NativeSessionRef,
